  List<String> groups = [];
  int openCount = 0;

  for (int i = 0; i < parenString.length; i++) {
    if (parenString[i] == '(') {
      openCount++;
    } else if (openCount > 0 && parenString[i] == ')') {
      openCount--;

      // If we've closed a group, add it to the result list.
      String currentGroup = '';
      while (i >= 0 && parenString[i] != ' ') {
        currentGroup = parenString[i--] + currentGroup;
      }
      groups.add(currentGroup);
