List<String> separateParenGroups(String parenString) {
  List<String> result = [];
  List<String> currentString = [];
  int currentDepth = 0;

  for (int i = 0; i < parenString.length; i++) {
    String c = parenString[i];
    if (c == '(') {
      currentDepth += 1;
      currentString.add(c);
    } else if (c == ')') {
      currentDepth -= 1;
      currentString.add(c);

      if (currentDepth == 0) {
        result.add(currentString.join(''));
        currentString.clear();
      }
    }
  }

  return result;
}

