bool correctBracketing(String brackets) {
  int open = 0;

  for (int i = 0; i < brackets.length; i++) {
    if (brackets[i] == '<') {
      open++;
    } else {
      open--;
    }

    // If at any point the number of closing brackets exceeds opening ones, it's invalid
    if (open < 0) return false;
  }

  // At the end, all opened brackets should be closed
