int maxFill(List<List<int>> grid, int capacity) {
  List<List<int>> filledGrid = [];

  for (var row in grid) {
    List<int> newRow = [];

    int filledCount = 0; // Track how many cells are already filled

    for (int cell in row) {
      if (cell == 1) {
        newRow.add(2); // Mark as filled
        filledCount++;
      } else {
        newRow.add(0); // Keep empty
      }
    }

    // Check if the number of filled cells exceeds the capacity
    while (filledCount > capacity && !newRow.isEmpty) {
      int firstFilledIndex = -1;

      // Find the index of the last '1' (i.e., a filled cell) that can be turned back to '0'
      for (int i = newRow.length - 1; i >= 0; i--) {
        if (newRow[i] == 2) {
          firstFilledIndex = i;
          break;
        }
      }

      // If there is at least one filled cell, turn it back to '0' and decrease count
      if (firstFilledIndex != -1) {
        newRow[firstFilledIndex] = 0;
        filledCount--;
      }
    }

    filledGrid.add(newRow);
  }

  return filledGrid.map((row) => row.where((x) => x == 2).length).reduce((a, b) => a + b);
}

