bool isNested(String string) {
  List<int> openingBracketIndex = [];
  List<int> closingBracketIndex = [];

  for (int i = 0; i < string.length; i++) {
    if (string[i] == '[') {
      openingBracketIndex.add(i);
    } else {
      closingBracketIndex.add(i);
    }
  }

  closingBracketIndex = closingBracketIndex.reversed.toList();

  int cnt = 0;
  int i = 0;
  int l = closingBracketIndex.length;

  for (int idx in openingBracketIndex) {
    if (i < l && idx < closingBracketIndex[i]) {
      cnt += 1;
      i += 1;
    }
  }

  return cnt >= 2;
}

