  if (lst.isEmpty || lst.length == 1) return [null, null];

  int min = lst[0], max = lst[0];

  for (int num in lst) {
    if (num < min) min = num;
    if (num > max) max = num;
  }

  List<int> result = [];
  while (min <= max && result.length < 2) {
    if (!result.contains(min)) result.add(min);
    else break;

    if (!result.contains(max)) result.add(max);
    else break;

    min++;
    max--;
  }

  List<dynamic> output = [];
  for (int i = result.length - 1; i >= 0; i--) {
    output.add(result[i]);
  }
  return output;
}

