      parts2.insert(i, ' '); // Insert a space where non-letters were removed
    } else if (parts1[i].length == 0 && parts2[i].length > 0) {
      parts2.removeAt(i); // Remove spaces that don't correspond to letters
    }
  }

  return parts2.join('');
}

